artifact.schema:
import type { ViewDefinition } from './view';

// ─── ROUTE — URL → step matching ────────────────────────────────────
export interface Route {
  readonly id:      string;             // 'products.list'
  readonly path:    PathPattern;        // '/productos' | '/productos/:id'
  readonly _match:  (url: string) => RouteMatch | null;  // computed by Trie at build
}

export function defineRoute(spec: {
  id:   string;
  path: PathPattern;
}): Route;

// ─── GUARD — precondition that can replace the step ─────────────────
export interface Guard {
  readonly id: string;
  readonly run: (ctx: GuardContext) => GuardResult | Promise<GuardResult>;
}

export type GuardResult =
  | { decision: 'allow' }
  | { decision: 'replace';  withStep: string; preserveIntent?: boolean }
  | { decision: 'redirect'; url: string }
  | { decision: 'deny';     reason: string };

export function defineGuard(spec: {
  id: string;
  run: Guard['run'];
}): Guard;

// ─── TRANSITIONS — declarative navigation ───────────────────────────
export interface Transitions {
  readonly [eventName: string]: TransitionTarget;
}

export type TransitionTarget =
  | { stepId: string;  params?: ReadonlyArray<string> }
  | { url: string }
  | { complete: true;  output?: unknown }
  | { fail: true;      error: string };

export function defineTransitions(t: Transitions): Transitions;

// ─── STEP — composition of the above ────────────────────────────────
export interface StepDefinition {
  readonly route:       Route;
  readonly guards:      ReadonlyArray<Guard>;
  readonly view:        ViewDefinition;
  readonly transitions: Transitions;
  readonly title?:      string | ((ctx: { params: Record<string,string> }) => string);
  readonly breadcrumbs?: BreadcrumbsFn;
}

export function defineStep(spec: {
  route:       Route;
  guards?:     ReadonlyArray<Guard>;
  view:        ViewDefinition;
  transitions?: Transitions;
  title?:       StepDefinition['title'];
  breadcrumbs?: BreadcrumbsFn;
}): StepDefinition;

artifact.example:
import { defineStep, defineRoute, defineTransitions } from '@surte/core';
import { authGuard, productsReadGuard } from '@surte/guards';
import { ProductListView, ProductCreateView, ProductDetailView } from '../views';

export const productListStep = defineStep({
  route:       defineRoute({ id: 'products.list', path: '/productos' }),
  guards:      [authGuard, productsReadGuard],
  view:        ProductListView,
  transitions: defineTransitions({
    create: { stepId: 'products.create' },
    open:   { stepId: 'products.detail', params: ['id'] },
  }),
  title:        'Productos',
  breadcrumbs:  () => [{ label: 'Productos' }],
});

export const productCreateStep = defineStep({
  route:       defineRoute({ id: 'products.create', path: '/productos/nuevo' }),
  guards:      [authGuard, productsWriteGuard],
  view:        ProductCreateView,
  transitions: defineTransitions({
    next:   { stepId: 'products.detail', params: ['id'] },
    cancel: { stepId: 'products.list' },
  }),
});

export const productDetailStep = defineStep({
  route:       defineRoute({ id: 'products.detail', path: '/productos/:id' }),
  guards:      [authGuard, productsReadGuard],
  view:        ProductDetailView,
  title:       ({ params }) => `Producto · ${params.id}`,
});
